import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

class Solution {
    private List<String> result;
    private Map<Character, String> map;

    public List<String> letterCombinations(String digits) {
        this.result = new ArrayList<>();
        // Guard Check: Always return empty list immediately if input is empty
        if (digits == null || digits.isEmpty()) {
            // Context: Avoids StringIndexOutOfBoundsException
            return result; 
        }

        // Initialize mapping dictionary
        this.map = new HashMap<>();
        map.put('2', "abc");  map.put('3', "def");  map.put('4', "ghi");
        map.put('5', "jkl");  map.put('6', "mno");  map.put('7', "pqrs");
        map.put('8', "tuv");  map.put('9', "wxyz");

        // Start backtracking with a shared StringBuilder starting at digit index 0
        backtrack(digits, 0, new StringBuilder());
        return result;
    }

    private void backtrack(String digits, int index, StringBuilder currentPath) {
        // Base Case: If the path length matches the digits length, we found a complete combination
        if (index == digits.length()) {
            result.add(currentPath.toString()); // O(N) copy happens ONLY here
            return;
        }

        // Get the letters corresponding to the current digit
        String letters = map.get(digits.charAt(index));

        // Loop through all available choices for this digit
        for (int i = 0; i < letters.length(); i++) {
            char c = letters.charAt(i);

            currentPath.append(c);                    // 1. Choose: Add character to path (O(1))
            backtrack(digits, index + 1, currentPath); // 2. Explore: Move to the next digit index
            currentPath.deleteCharAt(currentPath.length() - 1); // 3. Un-choose: Remove character (Backtrack) (O(1))
        }
    }
}
